/// <reference types="react" />
export interface OptionTypeWithKeyValue {
    key: string;
    label: string;
    disabled?: boolean;
}
export type ValueType = string[] | OptionTypeWithKeyValue[];
export type SingleOptionType = string | OptionTypeWithKeyValue;
export interface HeaderConfig {
    showFilterActionBar?: boolean;
    showFilterControls?: boolean;
    showSelectedChips?: boolean;
}
export type SelectedChipsProps = {
    selectedOptions: ValueType;
    getOptionKey: (option: SingleOptionType) => string;
    getOptionLabel: (option: SingleOptionType) => string;
    handleChipRemove: (option: string, event: React.MouseEvent) => void;
};
export type ActionButtonsProps = {
    shouldEnableActionButton: boolean;
    handleCancel: () => void;
    handleApply: () => void;
    cancelButtonText: string;
    applyButtonText: string;
};
export type MultiSelectHeaderProps = {
    selectedOptions: ValueType;
    applySelectAll: (event: React.MouseEvent<HTMLButtonElement>) => void;
    applyClearAll: (event: React.MouseEvent<HTMLButtonElement>) => void;
    getOptionKey: (option: SingleOptionType) => string;
    getOptionLabel: (option: SingleOptionType) => string;
    handleChipRemove: (option: string, event: React.MouseEvent) => void;
    headerConfig?: HeaderConfig;
};
export type OptionsListProps = {
    options: ValueType;
    selectedValue: string[];
    getOptionKey: (option: SingleOptionType) => string;
    getOptionLabel: (option: SingleOptionType) => string;
    getOptionDisabled: (option: SingleOptionType) => boolean;
    handleOptionToggle: (option: SingleOptionType) => void;
    noOptionsMessage: React.ReactNode;
    isHeaderSectionVisible: boolean;
    shouldEnableActionButton: boolean;
    isLoading?: boolean;
};
export type RenderOptionProps = {
    option: SingleOptionType;
    getOptionKey: (option: SingleOptionType) => string;
    getOptionLabel: (option: SingleOptionType) => string;
    getOptionDisabled: (option: SingleOptionType) => boolean;
    selectedValue: string[];
    handleOptionToggle: (option: SingleOptionType) => void;
    isHeaderSectionVisible: boolean;
    shouldEnableActionButton: boolean;
};
